# Pedidos das provas antigas que passam para o estilo pintado (01/11/2026, pedido do dono: "Monte os pedidos para todos os jogos").
# Lido por novas/pedidos.py (exec), depois de PIA, PBL, STYLE, KEEP e KEEPG. Parte 1: Surfe, Patins, Basquete, BMX, Corrida na areia, Frisbee.
OUT = 'Thick dark navy outline, hand-painted cartoon style, the same painting style as the attached MODEL SHEET. Flat pure green background (#00FF00), no text, no shadow.'
UPR = 'Draw every frame UPRIGHT (head up), even for the flip: the game rotates the whole drawing in the air. '
SEM = ' (do NOT draw it: the game draws it)'
HORA = {
  'manhã': 'EARLY MORNING: low golden sunlight from the left, light haze, long soft shadows, pale peach and lilac sky.',
  'entardecer': 'SUNSET: orange, pink and purple sky with glowing clouds, the sun low near the horizon, warm backlight, long shadows.',
  'noite': 'NIGHT: deep night-blue sky with many small stars and a thin crescent moon, cool moonlight.',
}
def horas(camadas, emenda=False):
    """os outros 3 horários de cada camada (o dia é a base). camadas: [(nome, fundo_verde, extra_noite, luzes_ou_None)]"""
    out = []; ed = ' The left and right edges must still match perfectly (it repeats sideways).' if emenda else ''
    for h in ['manhã', 'entardecer', 'noite']:
        for nome, verde, noite, luz in camadas:
            txt = KEEP + (KEEPG if verde else '') + HORA[h] + (' ' + noite + ' Still readable, not black.' if h == 'noite' else '') + ed
            out.append(dict(t=f'{nome} · {h}', sub=f'anexe: {nome.lower()} · dia', txt=txt))
    for nome, verde, noite, luz in camadas:
        if luz: out.append(dict(t=f'Luzes da noite · {nome.lower()}', sub=f'anexe: {nome.lower()} · noite', txt='Use the attached NIGHT image. Make an image of exactly the same size and framing that shows ONLY the lights, on a pure black background: ' + luz + ', each with a soft glow, in exactly the same positions as in the attached image. Everything else pure black. No text.'))
    return out
def modelo(nome, o_que, extra=''):
    return dict(t=f'Folha de modelo {nome}', sub='não é 4x2 · vira anexo das pranchas', txt=f'Also attached: the IAmiguinho MODEL SHEET (for the size). Sheet: {o_que} MODEL SHEET for this game (not a 4x2 grid), drawn in the same hand-painted cartoon style and thick dark navy outline as the character, at the right size next to him. ' + extra + ' Each view separate, with space around it. ' + OUT)
def giro(eq, pega):
    return dict(t='Giro no ar: 8 vistas', sub='8 quadros · o jogo gira por elas', txt=PIA + f'Also attached: the approved {eq}. Sheet: the SAME mid-air pose seen from 8 angles around him, for a spin: {pega}. 1 side view facing RIGHT, 2 three-quarter front, 3 front, 4 three-quarter front facing left, 5 side view facing LEFT, 6 three-quarter back facing left, 7 back, 8 three-quarter back facing right. Exactly the same pose, size and height in every frame, only the angle changes, like a turntable.')

